"""
gen_exp_lut.py - writes rtl/exp_lut.sv from golden.EXP_LUT
Run from the model/ folder: python gen_exp_lut.py
"""

from golden import EXP_LUT

lines = [
    "// AUTO-GENERATED by model/gen_exp_lut.py - do not edit by hand",
    "module exp_lut (",
    "    input  logic [9:0]  idx,",
    "    output logic [17:0] val);",
    "",
    "    always_comb begin",
    "        case (idx)",
]
for i, v in enumerate(EXP_LUT):
    lines.append(f"            10'd{i}: val = 18'd{v};")
lines += [
    "            default: val = 18'd0;",
    "        endcase",
    "    end",
    "endmodule: exp_lut",
    "",
]
with open("../rtl/exp_lut.sv", "w") as f:
    f.write("\n".join(lines))